style.css:
@-moz-document domain("youtube.com") {
/* Sayfa Arka Planı Şeffaf */
body, ytd-app, #page-manager, ytd-masthead, #guide-content, ytd-mini-guide-renderer, tp-yt-app-drawer {
  background-color: transparent !important;
  backdrop-filter: none !important;
}

/* Videolar, Başlıklar Neonlu */
#video-title, .title, ytd-video-meta-block, ytd-channel-name, ytd-thumbnail-overlay-time-status-renderer {
  color: #e0f7ff !important;
  text-shadow: 0 0 4px #ffffff, 0 0 6px #66ccff !important;
}

/* Thumbnail (Küçük Resim) Hover Neon */
ytd-thumbnail:hover {
  box-shadow: 0 0 20px #66ccff, 0 0 30px #e0f7ff !important;
  border-radius: 8px;
  transition: all 0.3s ease-in-out;
  transform: scale(1.02);
}

/* Butonlar Neonlu */
button, yt-icon-button, paper-button, ytd-subscribe-button-renderer {
  background-color: transparent !important;
  color: #e0f7ff !important;
  text-shadow: 0 0 8px #e0f7ff, 0 0 12px #66ccff !important;
  box-shadow: 0 0 8px #66ccff, 0 0 16px #ffffff !important;
  transition: all 0.2s ease-in-out;
  border: none !important;
}

/* Hover Efekti - Butonlar */
button:hover, yt-icon-button:hover, paper-button:hover, ytd-subscribe-button-renderer:hover {
  box-shadow: 0 0 12px #66ccff, 0 0 20px #ffffff !important;
  transform: scale(1.05);
}

/* Abone Ol Butonu Özel */
ytd-subscribe-button-renderer paper-button {
  background-color: rgba(0, 255, 255, 0.1) !important;
  border-radius: 6px;
  font-weight: bold;
}

/* Arama Kutusu - Bulanık Cam Efekti */
ytd-searchbox {
  background: rgba(0, 0, 0, 0.3) !important;
  backdrop-filter: blur(8px) brightness(1.1);
  border-radius: 12px;
  box-shadow: 0 0 10px #66ccff, 0 0 20px #e0f7ff;
}

/* Arama İçindeki Input Alanı */
ytd-searchbox input {
  background: transparent !important;
  color: #e0f7ff !important;
  border: none !important;
}

/* Navigasyon & Menüleri Şeffaf Yap */
#container.ytd-masthead, #end.ytd-masthead, ytd-mini-guide-renderer, tp-yt-app-drawer {
  background-color: transparent !important;
  backdrop-filter: none !important;
  border: none !important;
}

/* Video Bilgi Kartı Arka Planlarını Şeffaf Yap */
ytd-video-renderer, ytd-grid-video-renderer, ytd-rich-item-renderer {
  background-color: transparent !important;
  box-shadow: none !important;
}

/* Tooltip ve Diğer Metinler */
yt-formatted-string, .style-scope {
  color: #e0f7ff !important;
  text-shadow: 0 0 6px #66ccff !important;
}
}
